/* Shared themed menus; opt-in multi-select keeps native form values and keyboard behavior. */
let selectSequence=0,activeSelect=null;
function selectChevron(){return '<svg class="select-chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg>';}
function selectControl({name='',options,value='',attributes={},label='',multiple=false,exclusive=[],format='',search=false}){
 const id='shared-select-'+(++selectSequence),items=options.map(option=>typeof option==='object'?option:{value:option,label:option}),selected=items.find(item=>String(item.value)===String(value))||items[0],attrs=Object.entries(attributes).filter(([key])=>/^(data-[\w-]+|aria-[\w-]+|id|required|disabled)$/.test(key)).map(([key,val])=>val===true?key:val===false||val==null?'':`${key}="${escape(val)}"`).filter(Boolean).join(' ');
 const values=new Set((Array.isArray(value)?value:[value]).map(String));
 return `<span class="select-control"><select ${multiple?'multiple':''} ${search?'data-select-search':''} data-select-exclusive="${escape(JSON.stringify(exclusive))}" data-select-format="${escape(format)}" hidden aria-hidden="true" tabindex="-1" data-select-native ${name?`name="${escape(name)}"`:''} ${attrs}>${items.map(item=>`<option value="${escape(item.value)}" ${(multiple?values.has(String(item.value)):item===selected)?'selected':''} ${item.preset?`data-select-preset="${escape(item.preset.join(','))}"`:''} ${item.disabled?'disabled':''} ${item.detail?`data-select-detail="${escape(item.detail)}"`:''}>${escape(item.label)}</option>`).join('')}</select><button type="button" id="${id}" role="combobox" aria-label="${escape(attributes['aria-label']||label||name)}" aria-haspopup="listbox" aria-expanded="false" data-select-trigger ${attributes.disabled?'disabled':''}><span class="select-value">${escape(selected?.label||'Choose an option')}</span>${selectChevron()}</button></span>`;
}
function selectField({label,className='',...config}){const control=selectControl({...config,label}),id='shared-select-'+selectSequence;return `<div class="select-field ${escape(className)}"><label for="${id}">${escape(label)}</label>${control}</div>`;}
function selectValueText(native){if(!native.multiple)return native.selectedOptions[0]?.textContent||'Choose an option';const options=[...native.selectedOptions].filter(o=>!o.dataset.selectPreset);if(native.dataset.selectFormat==='days'){const days=options.map(o=>o.value).filter(v=>/^\d+$/.test(v));return options.some(o=>o.value==='off')?'Off':(days.length?days.join(', ')+' day'+(days.length===1&&days[0]==='1'?'':'s')+' before':'')+(options.some(o=>o.value==='custom')?(days.length?' + Custom days':'Custom days'):'');}return options.map(o=>o.textContent).join(', ')||'Choose options';}
function selectOptionSelected(native,option){return option.dataset.selectPreset?option.dataset.selectPreset.split(',').every(v=>[...native.selectedOptions].some(o=>o.value===v)):option.selected;}
function nextMultipleSelectValues(values,value,{exclusive=[],preset=[]}={}){const set=new Set(values.map(String));if(exclusive.includes(value))return [value];exclusive.forEach(v=>set.delete(v));const toggle=preset.length?preset:[value],remove=toggle.every(v=>set.has(v));toggle.forEach(v=>remove?set.delete(v):set.add(v));return set.size?[...set]:exclusive.slice(0,1);}
function syncSelectControls(){document.querySelectorAll('[data-select-native]').forEach(native=>{const trigger=native.parentElement.querySelector('[data-select-trigger]');trigger.querySelector('.select-value').textContent=selectValueText(native);trigger.disabled=native.disabled;});}
function closeSelectMenu(returnFocus=true){if(!activeSelect)return;const {trigger,overlay}=activeSelect;overlay.remove();trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-controls');trigger.removeAttribute('aria-activedescendant');activeSelect=null;if(returnFocus&&trigger.isConnected)trigger.focus();}
function highlightSelect(index,step=1){if(!activeSelect)return;const {native,trigger,overlay}=activeSelect,options=[...native.options];if(!options.length)return;let next=(index+options.length)%options.length;const skip=i=>options[i].disabled||overlay.querySelector(`[data-select-option="${i}"]`)?.hidden;if(options.every((_,i)=>skip(i)))return;for(let tries=0;tries<options.length&&skip(next);tries++)next=(next+step+options.length)%options.length;activeSelect.index=next;overlay.querySelectorAll('[data-select-option]').forEach((item,i)=>item.classList.toggle('is-highlighted',i===next));const option=overlay.querySelector(`[data-select-option="${next}"]`);trigger.setAttribute('aria-activedescendant',option.id);option.scrollIntoView({block:'nearest'});}
function openSelectMenu(trigger){if(activeSelect?.trigger===trigger){closeSelectMenu();return;}closeSelectMenu(false);const native=trigger.parentElement.querySelector('[data-select-native]'),phone=trigger.closest('.phone');if(!phone||native.disabled)return;const p=phone.getBoundingClientRect(),r=trigger.getBoundingClientRect(),style=getComputedStyle(phone),scale=p.width/phone.offsetWidth,borderLeft=parseFloat(style.borderLeftWidth)||0,borderTop=parseFloat(style.borderTopWidth)||0,triggerLeft=(r.left-p.left)/scale-borderLeft,triggerTop=(r.top-p.top)/scale-borderTop,triggerBottom=(r.bottom-p.top)/scale-borderTop,searchable=native.hasAttribute('data-select-search'),width=Math.min(searchable?Math.max(r.width/scale,236):r.width/scale,phone.clientWidth-32),left=Math.max(16,Math.min(triggerLeft,phone.clientWidth-width-16)),below=phone.clientHeight-triggerBottom-18,above=triggerTop-18,desired=Math.min(native.options.length*42+12,searchable?320:260),useAbove=below<desired&&above>below,maxHeight=Math.max(84,Math.min(searchable?320:260,useAbove?above:below)),overlay=document.createElement('div'),listId=trigger.id+'-options';overlay.className='select-menu-overlay';overlay.innerHTML=`<div class="select-dismiss" data-select-dismiss></div><div class="themed-select-menu" id="${listId}" role="listbox" ${native.multiple?'aria-multiselectable="true"':''} aria-label="${escape(trigger.getAttribute('aria-label'))} options" style="left:${left}px;width:${width}px;max-height:${maxHeight}px;${useAbove?'bottom:'+Math.max(16,phone.clientHeight-triggerTop+6)+'px':'top:'+(triggerBottom+6)+'px'}">${searchable?`<div class="select-search"><input type="search" placeholder="Search currency" aria-label="Search currencies" autocomplete="off" data-select-search-input></div>`:''}${[...native.options].map((option,i)=>`<button type="button" role="option" tabindex="-1" id="${listId}-${i}" data-select-option="${i}" aria-selected="${selectOptionSelected(native,option)}" ${option.disabled?'disabled aria-disabled="true"':''}><span>${escape(option.textContent)}${option.dataset.selectDetail?`<small>${escape(option.dataset.selectDetail)}</small>`:''}</span><svg class="select-option-check" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4 10-10"/></svg></button>`).join('')}${searchable?'<p class="select-empty" hidden>No currency found</p>':''}</div>`;phone.append(overlay);activeSelect={native,trigger,overlay,index:native.selectedIndex,typed:'',typedAt:0};trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls',listId);(overlay.querySelector('[data-select-search-input]')||trigger).focus();highlightSelect(Math.max(0,native.selectedIndex));}
function chooseSelect(index){if(!activeSelect)return;const {native,overlay}=activeSelect;if(!native.options[index]||native.options[index].disabled)return;if(native.multiple){const option=native.options[index],values=nextMultipleSelectValues([...native.selectedOptions].map(o=>o.value),option.value,{exclusive:JSON.parse(native.dataset.selectExclusive||'[]'),preset:option.dataset.selectPreset?.split(',')||[]});[...native.options].forEach(o=>o.selected=values.includes(o.value));syncSelectControls();overlay.querySelectorAll('[data-select-option]').forEach((el,i)=>el.setAttribute('aria-selected',String(selectOptionSelected(native,native.options[i]))));highlightSelect(index);}else{native.selectedIndex=index;syncSelectControls();closeSelectMenu();}native.dispatchEvent(new Event('change',{bubbles:true}));}
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-select-trigger]'),option=event.target.closest('[data-select-option]');if(trigger){event.preventDefault();openSelectMenu(trigger);}else if(option){event.preventDefault();chooseSelect(Number(option.dataset.selectOption));}else if(event.target.closest('[data-select-dismiss]'))closeSelectMenu();});
document.addEventListener('change',event=>{if(event.target.matches('[data-select-native]'))syncSelectControls();});
document.addEventListener('keydown',event=>{const trigger=event.target.closest('[data-select-trigger]');if(!trigger&&!activeSelect)return;if(!activeSelect){if(['ArrowDown','ArrowUp','Enter',' '].includes(event.key)){event.preventDefault();openSelectMenu(trigger);}return;}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closeSelectMenu();}else if(event.key==='Tab')closeSelectMenu(false);else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();highlightSelect(event.key==='Home'?0:event.key==='End'?activeSelect.native.options.length-1:activeSelect.index+(event.key==='ArrowDown'?1:-1),event.key==='ArrowUp'||event.key==='End'?-1:1);}else if(event.target.matches('[data-select-search-input]')&&event.key!=='Enter'){return;}else if(event.key==='Enter'||event.key===' '){event.preventDefault();chooseSelect(activeSelect.index);}else if(event.key.length===1&&!event.ctrlKey&&!event.metaKey){const now=Date.now();activeSelect.typed=now-activeSelect.typedAt>700?event.key:activeSelect.typed+event.key;activeSelect.typedAt=now;const index=[...activeSelect.native.options].findIndex(option=>!option.disabled&&option.textContent.toLowerCase().startsWith(activeSelect.typed.toLowerCase()));if(index>=0)highlightSelect(index);}});
function filterSelectMenu(query){if(!activeSelect)return;const q=query.trim().toLowerCase(),{overlay}=activeSelect;let first=-1;overlay.querySelectorAll('[data-select-option]').forEach((item,i)=>{item.hidden=!!q&&!item.textContent.toLowerCase().includes(q);if(!item.hidden&&first<0)first=i;});overlay.querySelector('.select-empty').hidden=first>=0;if(first>=0)highlightSelect(first);}
document.addEventListener('input',event=>{if(event.target.matches('[data-select-search-input]'))filterSelectMenu(event.target.value);});
